$('workBtn').onclick=()=>openFeature('work');$('jobsBtn').onclick=()=>openFeature('jobs');$('storeBtn').onclick=()=>openFeature('store');$('diagnoseBtn').onclick=()=>openFeature('diagnose');$('learnBtn').onclick=()=>openFeature('research');$('driveBtn').onclick=()=>openFeature('drive');$('shiftBtn').onclick=()=>openFeature('shift');$('homeBtn').onclick=()=>openFeature('home');$('worldBtn').onclick=()=>openFeature('world');$('sleepBtn').onclick=()=>openFeature('sleep');$('inventoryStat').onclick=()=>openFeature('inventory');$('toolsStat').onclick=()=>openFeature('tools');$('knowledgeStat').onclick=()=>openFeature('knowledge');$('confidenceStat').onclick=()=>openFeature('confidence');$('repStat').onclick=()=>openFeature('reputation');
function updateLayoutMode(){const portraitPhone=window.innerWidth<=600&&window.innerHeight>window.innerWidth;document.body.classList.toggle('portrait-phone',portraitPhone)}
$('menuBtn').onclick=()=>openGameMenu();$('seedBtn').onclick=()=>openRunInfo();$('olderLogBtn').onclick=()=>{logPageFromEnd++;renderLog()};$('newerLogBtn').onclick=()=>{logPageFromEnd=Math.max(0,logPageFromEnd-1);renderLog()};$('modal').addEventListener('click',e=>{if(e.target!==$('modal'))return;if(modalContext==='store')confirmLeaveStore(storeView);else closeModal()});window.addEventListener('resize',updateLayoutMode);window.addEventListener('orientationchange',updateLayoutMode);updateLayoutMode();initMainMenu();
